function palmaresRows(){const cls=palmaresClass.value,year=palmaresYear.value.trim(),period=palmaresPeriod.value;const students=data.students.filter(s=>s.class===cls&&s.status!=='transféré'&&s.status!=='abandonné');const subjects=[...new Set(data.grades.filter(g=>g.year===year&&g.period===period&&students.some(s=>s.id===g.studentId)).map(g=>g.subject))];const rows=students.map(s=>{const gs=gradesForStudent(s.id,year,period);const total=gs.reduce((a,g)=>a+Number(g.value||0),0),possible=gs.reduce((a,g)=>a+Number(g.maxScore||100),0),avg=possible?total/possible*10:0;const vals=subjects.map(sub=>{const g=gs.find(x=>x.subject===sub);return g?`${g.value}/${g.maxScore}`:'—'});return {s,total,possible,avg,vals}}).sort((a,b)=>b.avg-a.avg);rows.forEach((r,i)=>r.rank=r.avg>0?i+1:null);return {rows,subjects,cls,year,period}}
